mapper.select:
SELECT l.*, s.name AS student_name, s.student_no, COALESCE(l.letter_file_id, af.pk_archive_file) AS letter_file_id FROM archive_transfer_letter l LEFT JOIN student s ON l.student_id = s.pk_student LEFT JOIN archive_file af ON l.letter_file_path = af.file_path
AND l.student_id = #{studentId}
AND l.status = #{status}
ORDER BY l.create_time DESC

mapper.update:
UPDATE archive_transfer_letter
SET status = #{status},
    audit_user_id = #{auditUserId},
    audit_time = NOW(),
    audit_remark = #{auditRemark}
WHERE pk_letter = #{pkLetter}

UPDATE archive_transfer_letter
SET status = 3,
    send_user_id = #{sendUserId},
    send_time = NOW(),
    tracking_number = #{trackingNumber}
WHERE pk_letter = #{pkLetter}
